<style>
    .flag {
      display: inline-block;

      .flag-cloth {
          transform-box: fill-box;
          transform-origin: left center; 
          transition: transform 0.2s ease-out;
      }

      &:hover .flag-cloth {
          animation: flag-wave 0.6s ease-in-out infinite;
      }

      &:hover {
        path:nth-of-type(1) {
            fill: var(--primary-color-south-east);
            stroke: var(--secondary-color-south-east); 
            stroke-width: 1px;
        }
      }
    }

    @keyframes flag-wave {
        0% {
            transform: rotate(0deg) skewY(0deg);
        }
        25% {
            transform: rotate(2deg) skewY(-5deg) scaleX(0.95);
        }
        50% {
            transform: rotate(0deg) skewY(0deg) scaleX(1);
        }
        75% {
            transform: rotate(-2deg) skewY(5deg) scaleX(0.95);
        }
        100% {
            transform: rotate(0deg) skewY(0deg);
        }
    }
</style>